    public Object parseMarket(Object market)
    {
        //     {
        //       "symbol": "BTC",
        //       "tick_size": "1",
        //       "min_tick": "0",
        //       "max_tick": "1000000",
        //       "lot_size": "0.00001",
        //       "max_leverage": 50,
        //       "isolated_only": false,
        //       "min_order_size": "10",
        //       "max_order_size": "5000000",
        //       "funding_rate": "0.0000125",
        //       "next_funding_rate": "0.0000125",
        //       "created_at": 1748881333944,
        //       "instrument_type": "perpetual",
        //       "base_asset": "BTC"
        //     },
        //     {
        //       "symbol": "SOL-USDC",
        //       "tick_size": "0.01",
        //       "min_tick": "0",
        //       "max_tick": "1000000",
        //       "lot_size": "0.001",
        //       "max_leverage": 1,
        //       "isolated_only": false,
        //       "min_order_size": "10",
        //       "max_order_size": "1000000",
        //       "funding_rate": "0",
        //       "next_funding_rate": "0",
        //       "created_at": 1776615970246,
        //       "instrument_type": "spot",
        //       "base_asset": "SOL"
        //     },
        Object id = this.safeString(market, "symbol");
        Object baseId = this.safeString(market, "base_asset", id);
        Object instrumentType = this.safeString(market, "instrument_type");
        Object isSpot = (Helpers.isEqual(instrumentType, "spot"));
        Object isSwap = !Helpers.isTrue(isSpot);
        Object quoteId = "USDC";
        Object settleId = null;
        Object type = "spot";
        Object linear = null;
        Object inverse = null;
        Object contractSize = null;
        Object minLeverage = null;
        Object maxLeverage = null;
        Object crossMargin = null;
        Object isolatedMargin = null;
        if (Helpers.isTrue(Helpers.isEqual(id, null)))
        {
            throw new ExchangeError((String)Helpers.add(this.id, " parseMarket() missing id")) ;
        }
        if (Helpers.isTrue(isSpot))
        {
            Object idParts = Helpers.split(id, "-");
            quoteId = this.safeString(idParts, 1, quoteId);
        }
        Object isolatedOnly = this.safeBool(market, "isolated_only", false);
        if (Helpers.isTrue(isSwap))
        {
            settleId = quoteId;
            type = "swap";
            linear = true;
            inverse = false;
            contractSize = this.parseNumber("1");
            minLeverage = 1;
            maxLeverage = this.safeInteger(market, "max_leverage");
            crossMargin = !Helpers.isEqual(isolatedOnly, true);
            isolatedMargin = true;
        }
        Object base = this.safeCurrencyCode(baseId);
        Object quote = this.safeCurrencyCode(quoteId);
        Object settle = this.safeCurrencyCode(settleId);
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        if (Helpers.isTrue(isSwap))
        {
            symbol = Helpers.add(Helpers.add(symbol, ":"), settle);
        }
        Object fees = this.safeDict(this.fees, type, new java.util.HashMap<String, Object>() {{}});
        Object taker = this.safeNumber(fees, "taker");
        Object maker = this.safeNumber(fees, "maker");
        Object amountPrecision = this.safeNumber(market, "lot_size");
        Object pricePrecision = this.safeNumber(market, "tick_size");
        Object active = true; // there is no non-active markets comes from endpoint market info
        final Object finalId = id;
        final Object finalSymbol = symbol;
        final Object finalBase = base;
        final Object finalQuoteId = quoteId;
        final Object finalSettleId = settleId;
        final Object finalType = type;
        final Object finalLinear = linear;
        final Object finalInverse = inverse;
        final Object finalContractSize = contractSize;
        final Object finalMinLeverage = minLeverage;
        final Object finalMaxLeverage = maxLeverage;
        final Object finalCrossMargin = crossMargin;
        final Object finalIsolatedMargin = isolatedMargin;
        return this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
            put( "id", finalId );
            put( "symbol", finalSymbol );
            put( "base", finalBase );
            put( "quote", quote );
            put( "settle", settle );
            put( "baseId", baseId );
            put( "quoteId", finalQuoteId );
            put( "settleId", finalSettleId );
            put( "type", finalType );
            put( "spot", isSpot );
            put( "margin", false );
            put( "swap", isSwap );
            put( "future", false );
            put( "option", false );
            put( "active", active );
            put( "contract", isSwap );
            put( "linear", finalLinear );
            put( "inverse", finalInverse );
            put( "taker", taker );
            put( "maker", maker );
            put( "contractSize", finalContractSize );
            put( "expiry", null );
            put( "expiryDatetime", null );
            put( "strike", null );
            put( "optionType", null );
            put( "precision", new java.util.HashMap<String, Object>() {{
                put( "amount", amountPrecision );
                put( "price", pricePrecision );
            }} );
            put( "limits", new java.util.HashMap<String, Object>() {{
                put( "leverage", new java.util.HashMap<String, Object>() {{
                    put( "min", finalMinLeverage );
                    put( "max", finalMaxLeverage );
                }} );
                put( "amount", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "price", new java.util.HashMap<String, Object>() {{
                    put( "min", Pacifica.this.safeNumber(market, "min_tick") );
                    put( "max", Pacifica.this.safeNumber(market, "max_tick") );
                }} );
                put( "cost", new java.util.HashMap<String, Object>() {{
                    put( "min", Pacifica.this.safeNumber(market, "min_order_size") );
                    put( "max", Pacifica.this.safeNumber(market, "max_order_size") );
                }} );
            }} );
            put( "created", Pacifica.this.safeInteger(market, "created_at") );
            put( "marginModes", new java.util.HashMap<String, Object>() {{
                put( "cross", finalCrossMargin );
                put( "isolated", finalIsolatedMargin );
            }} );
            put( "info", market );
        }});
    }

    /**
     * @method
     * @name pacifica#fetchBalance
     * @description query for balance and get the amount of funds available for trading or funds locked in orders
     * @see https://docs.pacifica.fi/api-documentation/api/rest-api/account/get-account-info
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.account] will default to walletAddress if not provided
     * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Balances> fetchBalance(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            Object userAccount = null;
            var userAccountparametersVariable = this.handleOriginAndSingleAddress("fetchBalance", parameters);
            userAccount = ((java.util.List<Object>) userAccountparametersVariable).get(0);
            parameters = ((java.util.List<Object>) userAccountparametersVariable).get(1);
            final Object finalUserAccount = userAccount;
            Object request = new java.util.HashMap<String, Object>() {{
                put( "account", finalUserAccount );
            }};
            Object response = (this.publicGetAccount(this.extend(request, parameters))).join();
            // {
            //   "success": true,
            //   "data": {
            //     "balance": "2000.000000",
            //     "fee_level": 0,
            //     "maker_fee": "0.00015",
            //     "taker_fee": "0.0004",
            //     "account_equity": "2150.250000",
            //     "available_to_spend": "1800.750000",
            //     "available_to_withdraw": "1500.850000",
            //     "pending_balance": "0.000000",
            //     "total_margin_used": "349.500000",
            //     "cross_mmr": "420.690000",
            //     "positions_count": 2,
            //     "orders_count": 3,
            //     "stop_orders_count": 1,
            //     "updated_at": 1716200000000,
            //     "use_ltp_for_stop_orders": false
            //   },
            //   "error": null,
            //   "code": null
            // }
            Object data = this.safeDict(response, "data", new java.util.HashMap<String, Object>() {{}});
            Object result = new java.util.HashMap<String, Object>() {{
                put( "info", data );
            }};
            Helpers.addElementToObject(result, "free", new java.util.HashMap<String, Object>() {{}});
            Helpers.addElementToObject(result, "used", new java.util.HashMap<String, Object>() {{}});
            Helpers.addElementToObject(result, "total", new java.util.HashMap<String, Object>() {{}});
            Object totalBalance = this.safeNumber(data, "account_equity");
            Object usedMargin = this.safeNumber(data, "total_margin_used");
            Object freeBalance = this.safeNumber(data, "available_to_spend");
            Helpers.addElementToObject(Helpers.GetValue(result, "total"), "USDC", totalBalance);
            Helpers.addElementToObject(Helpers.GetValue(result, "used"), "USDC", usedMargin);
            Helpers.addElementToObject(Helpers.GetValue(result, "free"), "USDC", freeBalance);
            Object timestamp = this.safeInteger(data, "updated_at");
            Helpers.addElementToObject(result, "timestamp", timestamp);
            Helpers.addElementToObject(result, "datetime", this.iso8601(timestamp));
            return this.safeBalance(result);
        }).thenApply(io.github.ccxt.TypedCores::toBalances);

    }

    /**
     * @method
     * @name pacifica#fetchLeverage
     * @description fetch the set leverage for a market
     * @see https://docs.pacifica.fi/api-documentation/api/rest-api/account/get-account-settings
     * @param {string} symbol  unified symbol of the market
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.account] will default to walletAddress if not provided
     * @returns {object} a [leverage structure]{@link https://docs.ccxt.com/?id=leverage-structure}
     */
    public java.util.concurrent.CompletableFuture<io.github.ccxt.types.Leverage> fetchLeverage(Object symbol, Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            (this.loadAccountSettings()).join();
            if (Helpers.isTrue(Helpers.isEqual(this.markets, null)))
            {
                (this.loadMarkets()).join();
            }
            Object market = this.market(symbol);
            Object userAccount = null;
            var userAccountparametersVariable = this.handleOriginAndSingleAddress("fetchLeverage", parameters);
            userAccount = ((java.util.List<Object>) userAccountparametersVariable).get(0);
            parameters = ((java.util.List<Object>) userAccountparametersVariable).get(1);
            Object cacheAddress = this.walletAddress;
            Object settings = null;
            if (Helpers.isTrue(Helpers.isEqual(userAccount, cacheAddress)))
            {
                settings = this.handleOption("fetchLeverage", "settings");
            } else
            {
                final Object finalUserAccount = userAccount;
                Object request = new java.util.HashMap<String, Object>() {{
                    put( "account", finalUserAccount );
                }};
                settings = (this.fetchAccountSettings(this.extend(request, parameters))).join();
            }
            Object setting = this.safeDict(settings, symbol);
            if (Helpers.isTrue(Helpers.isEqual(setting, null)))
            {
                // NOTE: Upon account creation, all markets have margin settings default to cross margin and leverage default to max.
                // When querying this endpoint, all markets with default margin and leverage settings on this account will return blank.
                return this.parseLeverageFromMarket(market);
            } else
            {
                return this.parseLeverageFromSetting(symbol, setting);
            }
        }).thenApply(io.github.ccxt.TypedCores::toLeverage);

    }

    public Object parseLeverageFromSetting(Object symbol, Object setting)
    {
        // {
        //   "WLFI/USDC:USDC": {
        //       "symbol": "WLFI",
        //       "isolated": false,
        //       "leverage": 5,
        //       "created_at": 1758085929703,
        //       "updated_at": 1758086074002
        //    },
        // }
        Object isIsolated = this.safeBool(setting, "isolated", false);
        Object leverage = this.safeInteger(setting, "leverage");
        Object marginMode = ((Helpers.isTrue((Helpers.isEqual(isIsolated, true))))) ? "isolated" : "cross";
        return new java.util.HashMap<String, Object>() {{
            put( "info", setting );
            put( "symbol", symbol );
            put( "marginMode", marginMode );
            put( "longLeverage", leverage );
            put( "shortLeverage", leverage );
        }};
    }

    public Object parseLeverageFromMarket(Object market)
    {
        Object marketLimits = this.safeDict(market, "limits", new java.util.HashMap<String, Object>() {{}});
        Object leverageLimits = this.safeDict(marketLimits, "leverage", new java.util.HashMap<String, Object>() {{}});
        return new java.util.HashMap<String, Object>() {{
            put( "info", market );
            put( "symbol", Pacifica.this.safeString(market, "symbol") );
            put( "marginMode", Pacifica.this.handleOption("fetchLeverage", "defaultMarginMode", "cross") );
            put( "longLeverage", Pacifica.this.safeInteger(leverageLimits, "max") );
            put( "shortLeverage", Pacifica.this.safeInteger(leverageLimits, "max") );
        }};
    }

